import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late ValueNotifier<List<NewsModel>> _newsListNotifier;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCacheThenNetwork();
  }

  @override
  void dispose() {
    _newsListNotifier.dispose();
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  void _loadCacheThenNetwork() {
    final newsRepository = context.read<NewsRepository>();

    // Начальный пустой список для ValueNotifier
    _newsListNotifier = ValueNotifier(const <NewsModel>[]);

    // Шаг 1: мгновенно показываем кэш (только БД, сеть не дергается)
    newsRepository.loadNewsFeed(NewsFeedFilter.all).then((List<NewsModel> value) {
      if (!mounted) return;
      setState(() {
        _newsListNotifier.value = value;
      });
      _scaleController.forward(); // запускаем анимацию после показа кэша
    });

    // Шаг 2: параллельно фоновая загрузка из сети + запись в кэш
    newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {
      if (!mounted) return;
      setState(() {
        _newsListNotifier.value = value;
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ValueListenableBuilder<List<NewsModel>>(
        valueListenable: _newsListNotifier,
        builder: (BuildContext context, List<NewsModel> data, _) {
          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (BuildContext context, int index) {
                final NewsModel news = data[index];

                return Padding(
                  key: ValueKey(news.link),
                  padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}
